//! Read-only flat-file header store used on the proving hot path.
//!
//! `headers.db` (SQLite, see [`crate::db`]) stays the system of record: it's
//! what P2P sync writes to and what out-of-band tooling queries. This module
//! reads a `headers.bin` snapshot of it instead — a plain file of fixed-size
//! records, one per height, generated by `zkpow-cli dump-bin` and read back
//! with targeted seeks rather than a whole-file load. It's read-only by
//! design: nothing here writes to `headers.bin`, so there's no concurrent
//! writer to guard against.

use std::{
    fs::File,
    io,
    os::unix::fs::FileExt,
    path::Path,
};

use zkpow_core::{
    requires_median_hint, BlockHash, BlockTimestamp, ChainWork, CompactTarget, Header, HeaderInput, State,
    WINDOW_SIZE,
};
use zkpow_params::Consensus;

use crate::db::{genesis_state_from_record, HeaderBatchWitness, HeaderRecord};

/// Bytes per record: `height(4) + version(4) + prev_blockhash(32) +
/// merkle_root(32) + timestamp(4) + n_bits(4) + nonce(4) + chainwork(32) +
/// median_time_past(4) + ordered_timestamp_run(4)`.
pub const HEADER_RECORD_SIZE: usize = 124;

fn encode_record(height: u64, record: &HeaderRecord) -> [u8; HEADER_RECORD_SIZE] {
    let mut buf = [0u8; HEADER_RECORD_SIZE];
    let h = &record.header;
    buf[0..4].copy_from_slice(&(height as u32).to_le_bytes());
    buf[4..8].copy_from_slice(&h.version.to_le_bytes());
    buf[8..40].copy_from_slice(h.prev_blockhash.as_inner());
    buf[40..72].copy_from_slice(&h.merkle_root);
    buf[72..76].copy_from_slice(&h.timestamp.into_inner().to_le_bytes());
    buf[76..80].copy_from_slice(&h.compact_target.into_inner().to_le_bytes());
    buf[80..84].copy_from_slice(&h.nonce.to_le_bytes());
    buf[84..116].copy_from_slice(&record.chain_work.to_le_bytes());
    buf[116..120].copy_from_slice(&record.median_time_past.into_inner().to_le_bytes());
    buf[120..124].copy_from_slice(&(record.ordered_timestamp_run as u32).to_le_bytes());
    buf
}

fn decode_record(buf: &[u8; HEADER_RECORD_SIZE]) -> (u64, HeaderRecord) {
    let height = u32::from_le_bytes(buf[0..4].try_into().unwrap()) as u64;
    let version = u32::from_le_bytes(buf[4..8].try_into().unwrap());
    let prev_blockhash = BlockHash::new(buf[8..40].try_into().unwrap());
    let merkle_root: [u8; 32] = buf[40..72].try_into().unwrap();
    let timestamp = BlockTimestamp::new(u32::from_le_bytes(buf[72..76].try_into().unwrap()));
    let compact_target = CompactTarget::new(u32::from_le_bytes(buf[76..80].try_into().unwrap()));
    let nonce = u32::from_le_bytes(buf[80..84].try_into().unwrap());
    let chain_work = ChainWork::from_le_bytes(buf[84..116].try_into().unwrap());
    let median_time_past = BlockTimestamp::new(u32::from_le_bytes(buf[116..120].try_into().unwrap()));
    let ordered_timestamp_run = u32::from_le_bytes(buf[120..124].try_into().unwrap()) as u64;
    assert!(
        ordered_timestamp_run <= height,
        "headers.bin: invalid ordered_timestamp_run {ordered_timestamp_run} at height {height}; regenerate it with `zkpow-cli dump-bin`"
    );

    (
        height,
        HeaderRecord {
            height,
            header: Header {
                version,
                prev_blockhash,
                merkle_root,
                timestamp,
                compact_target,
                nonce,
            },
            chain_work,
            median_time_past,
            ordered_timestamp_run,
        },
    )
}

/// Write `records` (already in ascending-height order starting at height 0,
/// one entry per height with no gaps) to `path` as a `headers.bin` snapshot.
pub fn write_snapshot(path: impl AsRef<Path>, records: &[HeaderRecord]) -> io::Result<()> {
    let mut bytes = Vec::with_capacity(records.len() * HEADER_RECORD_SIZE);
    for (height, record) in records.iter().enumerate() {
        assert_eq!(record.height, height as u64, "records must be dense, ascending from height 0");
        bytes.extend_from_slice(&encode_record(height as u64, record));
    }
    std::fs::write(path, bytes)
}

/// Read-only reader over a `headers.bin` snapshot. Reads are targeted seeks
/// (`pread`), not a whole-file load — safe to construct once and reuse for
/// the life of a process.
pub struct HeaderBinReader {
    file: File,
    record_count: u64,
}

impl HeaderBinReader {
    pub fn open(path: impl AsRef<Path>) -> io::Result<Self> {
        let file = File::open(path)?;
        let len = file.metadata()?.len();
        assert!(
            len % HEADER_RECORD_SIZE as u64 == 0,
            "headers.bin length {len} is not a multiple of the {HEADER_RECORD_SIZE}-byte record size; regenerate it with `zkpow-cli dump-bin`"
        );
        Ok(Self {
            file,
            record_count: len / HEADER_RECORD_SIZE as u64,
        })
    }

    pub fn header_count(&self) -> u64 {
        self.record_count
    }

    fn read_record_at(&self, height: u64) -> HeaderRecord {
        let mut buf = [0u8; HEADER_RECORD_SIZE];
        self.file
            .read_exact_at(&mut buf, height * HEADER_RECORD_SIZE as u64)
            .unwrap_or_else(|err| panic!("headers.bin: failed to read record at height {height}: {err}"));
        let (decoded_height, record) = decode_record(&buf);
        assert_eq!(decoded_height, height, "headers.bin: record at byte offset for height {height} is stamped {decoded_height}");
        record
    }

    /// Records `[start_height, start_height + count)`, clamped to what's on
    /// disk (mirrors the SQL store's `WHERE height < ?` naturally stopping
    /// at the last available row).
    pub fn load_header_records(&self, start_height: u64, count: u64) -> Vec<HeaderRecord> {
        let available = self.record_count.saturating_sub(start_height);
        let actual_count = count.min(available);
        (start_height..start_height + actual_count).map(|h| self.read_record_at(h)).collect()
    }

    pub fn load_header_record(&self, height: u64) -> HeaderRecord {
        self.read_record_at(height)
    }

    pub fn load_new_headers(&self, start_height: u64, count: u64) -> Vec<HeaderInput> {
        self.load_header_batch_witness(start_height, count).headers
    }

    fn load_ordered_timestamp_run(&self, height: u64) -> u64 {
        self.read_record_at(height).ordered_timestamp_run
    }

    pub fn load_header_batch_witness(&self, start_height: u64, count: u64) -> HeaderBatchWitness {
        let records = self.load_header_records(start_height, count);

        let mut headers = Vec::with_capacity(records.len());
        let mut median_time_past_hints = Vec::with_capacity(records.len());
        let mut previous_ordered_timestamp_run = if start_height == 0 {
            0
        } else {
            self.load_ordered_timestamp_run(start_height - 1)
        };
        for record in &records {
            headers.push(HeaderInput {
                version: record.header.version,
                merkle_root: record.header.merkle_root,
                timestamp: record.header.timestamp,
                nonce: record.header.nonce,
            });
            if requires_median_hint(record.height, previous_ordered_timestamp_run) {
                median_time_past_hints.push(record.median_time_past);
            }
            previous_ordered_timestamp_run = record.ordered_timestamp_run;
        }
        HeaderBatchWitness {
            headers,
            median_time_past_hints,
        }
    }

    /// Reconstruct full consensus state at an arbitrary height.
    pub fn state_at_height<C: Consensus>(&self, height: u32, genesis_hash: BlockHash) -> State {
        if height == 0 {
            return genesis_state_from_record(self.load_header_record(0), genesis_hash);
        }

        let epoch_length = C::PARAMS.epoch_length;
        let epoch_start_height = (height / epoch_length) * epoch_length;
        let epoch_start = self.load_header_record(epoch_start_height as u64);
        let window_count = (height as usize + 1).min(WINDOW_SIZE) as u64;
        let window_start = height as u64 + 1 - window_count;
        let window = self.load_header_records(window_start, window_count);

        let mut timestamps = [BlockTimestamp::default(); WINDOW_SIZE];
        for r in &window {
            timestamps[r.height as usize % WINDOW_SIZE] = r.header.timestamp;
        }
        let current = window.last().expect("window covers the requested height");

        State {
            block_hash: BlockHash::from(&current.header),
            genesis_hash,
            current_nbits: current.header.compact_target,
            height,
            chain_work: current.chain_work,
            epoch_start_timestamp: epoch_start.header.timestamp,
            timestamps,
        }
    }
}
